/* Concise standard house meanings approved by the user; reference text only. */
(()=>{'use strict';
const ROMAN=['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'];
const HOUSE_MEANINGS=[
 {en:['Self and vitality','Body, appearance and constitution','Personality, temperament and confidence','General health and vitality','Personal initiative and approach to life'],mr:['स्वतः आणि व्यक्तिमत्त्व','शरीर, रूप आणि प्रकृती','स्वभाव, व्यक्तिमत्त्व आणि आत्मविश्वास','सर्वसाधारण आरोग्य आणि जीवनशक्ती','स्वतःचा पुढाकार आणि जीवनाकडे पाहण्याची दृष्टी']},
 {en:['Family and accumulated wealth','Savings, accumulated assets and finances','Family and family resources','Speech, voice and food habits','Values and material security'],mr:['कुटुंब आणि संचित धन','बचत, संचित संपत्ती आणि आर्थिक स्थिती','कुटुंब आणि कौटुंबिक साधनसंपत्ती','वाणी, आवाज आणि आहाराच्या सवयी','मूल्ये आणि आर्थिक सुरक्षितता']},
 {en:['Effort and communication','Courage, initiative and practical skills','Younger siblings and neighbours','Writing, messages and communication','Short journeys and everyday movement'],mr:['प्रयत्न आणि संवाद','धैर्य, पुढाकार आणि कौशल्ये','धाकटी भावंडे आणि शेजारी','लेखन, संदेश आणि संवाद','लहान प्रवास आणि दैनंदिन ये-जा']},
 {en:['Home and inner comfort','Mother and maternal care','Home, land, property and vehicles','Foundational education and learning','Domestic happiness and emotional security'],mr:['घर आणि मानसिक सुख','आई आणि मातृसुख','घर, जमीन, मालमत्ता आणि वाहने','प्राथमिक शिक्षण आणि अध्ययन','गृहसौख्य आणि मानसिक सुरक्षितता']},
 {en:['Children and creativity','Children and matters of parenthood','Intelligence, learning and creative expression','Romance, recreation and interests','Speculation, judgement and traditional mantra practice'],mr:['संतती आणि सर्जनशीलता','संतती आणि पालकत्वाशी संबंधित विषय','बुद्धिमत्ता, अध्ययन आणि सर्जनशीलता','प्रेमसंबंध, मनोरंजन आणि आवडी','सट्टा, निर्णयक्षमता आणि मंत्रोपासना']},
 {en:['Service and challenges','Employment, service and daily work','Illness, treatment and health routines','Debts, disputes and competition','Obstacles, opponents and problem solving'],mr:['सेवा आणि अडचणी','नोकरी, सेवा आणि दैनंदिन काम','आजार, उपचार आणि आरोग्याची दिनचर्या','कर्ज, वाद आणि स्पर्धा','अडथळे, विरोधक आणि समस्यांचे निराकरण']},
 {en:['Marriage and partnership','Spouse, marriage and committed relationships','Business partnerships and agreements','Trade, clients and public dealings','Negotiations and direct opponents'],mr:['विवाह आणि भागीदारी','जोडीदार, विवाह आणि वैवाहिक संबंध','व्यावसायिक भागीदारी आणि करार','व्यापार, ग्राहक आणि लोकसंपर्क','वाटाघाटी आणि समोरचे प्रतिस्पर्धी']},
 {en:['Longevity and transformation','Longevity and major life changes','Joint assets, inheritance and legacies','Research, hidden matters and confidential work','Sudden disruptions, vulnerability and recovery'],mr:['आयुष्य आणि परिवर्तन','आयुर्मान आणि जीवनातील मोठे बदल','संयुक्त संपत्ती, वारसा आणि मृत्युपत्रातील लाभ','संशोधन, गुप्त विषय आणि गोपनीय काम','अचानक बदल, संकटे आणि त्यातून सावरणे']},
 {en:['Fortune and higher learning','Higher education, philosophy and wisdom','Faith, religious practice and ethical principles','Father, teachers, mentors and guidance','Long journeys and pilgrimage'],mr:['भाग्य आणि उच्च शिक्षण','उच्च शिक्षण, तत्त्वज्ञान आणि ज्ञान','श्रद्धा, धर्माचरण आणि नैतिक मूल्ये','वडील, शिक्षक, गुरु आणि मार्गदर्शन','दूरचे प्रवास आणि तीर्थयात्रा']},
 {en:['Career and public standing','Profession, vocation and responsibilities','Status, reputation and public recognition','Authority, administration and leadership','Actions, achievements and contribution to society'],mr:['कर्म आणि व्यवसाय','व्यवसाय, कारकीर्द आणि जबाबदाऱ्या','प्रतिष्ठा, लौकिक आणि सामाजिक मान्यता','अधिकार, प्रशासन आणि नेतृत्व','कार्य, यश आणि समाजातील योगदान']},
 {en:['Gains and fulfilment','Income, profits and gains','Fulfilment of aims and wishes','Friends, networks and social groups','Elder siblings and support from associates'],mr:['लाभ आणि इच्छापूर्ती','उत्पन्न, नफा आणि लाभ','ध्येयांची पूर्तता आणि इच्छापूर्ती','मित्र, संपर्कजाळे आणि सामाजिक समूह','मोठी भावंडे आणि सहकाऱ्यांचा आधार']},
 {en:['Expenditure and withdrawal','Expenses, losses and charitable giving','Foreign residence and distant places','Sleep, solitude, hospitals and seclusion','Renunciation, spiritual retreat and liberation'],mr:['व्यय आणि एकांत','खर्च, नुकसान आणि दानधर्म','परदेशातील वास्तव्य आणि दूरची ठिकाणे','झोप, एकांत, रुग्णालये आणि बंदिस्त वास्तव्य','त्याग, साधना आणि मोक्षविचार']}
];
let dialog=null,selected=0,returnFocus=null,queued=false;
function language(){return window.KPPreferences?.get?.().language||'english';}
function node(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;}
function get(house,lang=language()){const item=HOUSE_MEANINGS[house-1];if(!item)return null;return {house,language:lang,title:lang==='marathi'?item.mr[0]:item.en[0],meanings:[...(lang==='marathi'?item.mr:item.en)].slice(1)};}
function render(){if(!dialog||!selected)return;const lang=language(),mr=lang==='marathi',both=lang==='bilingual',title=dialog.querySelector('h2'),content=dialog.querySelector('.kp-bhava-content');dialog.lang=mr?'mr':both?'en-mr':'en';title.textContent=mr?'भाव '+selected+' · कारकत्व':both?'Bhava '+selected+' · भाव कारकत्व':'Bhava '+selected+' · Significations';dialog.querySelector('button').textContent=mr?'बंद करा':both?'Close · बंद करा':'Close';dialog.querySelector('button').setAttribute('aria-label',mr?'कारकत्व बंद करा':'Close house significations');content.replaceChildren();for(const locale of both?['english','marathi']:[mr?'marathi':'english']){const data=get(selected,locale),section=node('section');section.lang=locale==='marathi'?'mr':'en';section.append(node('h3',data.title));const list=node('ul');for(const text of data.meanings)list.append(node('li',text));section.append(list);content.append(section);}}
function ensureDialog(){if(dialog)return;dialog=node('dialog');dialog.id='kp-bhava-karkatva-dialog';dialog.className='no-print';dialog.setAttribute('data-no-localize','');dialog.setAttribute('aria-labelledby','kp-bhava-karkatva-title');const header=node('header'),title=node('h2');title.id='kp-bhava-karkatva-title';const close=node('button');close.type='button';close.onclick=()=>dialog.close();header.append(title,close);const content=node('div');content.className='kp-bhava-content';dialog.append(header,content);dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});});dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();});document.body.append(dialog);}
function open(house,origin){house=Number(house);if(!Number.isInteger(house)||house<1||house>12)return false;ensureDialog();selected=house;returnFocus=origin||document.activeElement;render();if(!dialog.open)dialog.showModal();dialog.querySelector('button').focus();return true;}
function mark(label,house){house=Number(house);if(!label||!Number.isInteger(house)||house<1||house>12)return;label.dataset.bhavaKarkatva=String(house);label.setAttribute('role','button');label.setAttribute('tabindex','0');const mr=language()==='marathi';label.setAttribute('aria-label',mr?'भाव '+house+' · कारकत्व पाहा':'Bhava '+house+' · View significations');label.setAttribute('aria-haspopup','dialog');}
function decorate(){queued=false;document.querySelectorAll('#tc-cusps tr[data-house],#tc-cusp-nakshatras tr[data-house]').forEach(e=>mark(e.firstElementChild,e.dataset.house));document.querySelectorAll('#tc-bhav-chart [data-bhava],#tc-bhav-chart svg g[data-house]>text:first-child').forEach(e=>mark(e,e.dataset.bhava||e.parentElement.dataset.house));document.querySelectorAll('#kundali .v38-cusp,#home-kundali .v38-cusp,#na-native-chart .v38-cusp').forEach(e=>mark(e.querySelector('.v38-name'),e.dataset.cusp));document.querySelectorAll('#kundali-north svg text[data-cusp],#home-kundali svg text[data-cusp],#na-native-chart svg text[data-cusp]').forEach(e=>mark(e,e.dataset.cusp));}
function schedule(){if(!queued){queued=true;requestAnimationFrame(decorate);}}
function init(){decorate();const observer=new MutationObserver(schedule);for(const id of ['tc-bhav-chart','tc-cusps','tc-cusp-nakshatras','kundali','kundali-north','home-kundali','na-native-chart']){const e=document.getElementById(id);if(e)observer.observe(e,{childList:true,subtree:true});}document.addEventListener('click',event=>{const target=event.target.closest?.('[data-bhava-karkatva]');if(target){event.preventDefault();event.stopPropagation();open(target.dataset.bhavaKarkatva,target);}},true);document.addEventListener('keydown',event=>{if(!['Enter',' '].includes(event.key))return;const target=event.target.closest?.('[data-bhava-karkatva]');if(target){event.preventDefault();event.stopPropagation();open(target.dataset.bhavaKarkatva,target);}},true);window.addEventListener('kp-preferences-changed',()=>{decorate();if(dialog?.open)render();});}
window.KPBhavaKarkatva=Object.freeze({get,open,refresh:decorate});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
